contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient, uint amount) public payable {
        require(address(this).balance >= amount, "insufficient balance");
        require(recipient != address(0), "zero recipient");

        uint beforeContractBalance = address(c).balance;
        uint beforeRecipientBalance = address(recipient).balance;

        bool reverted;
        try c.getFirstWithdrawalBonus{value: amount}(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterContractBalance = address(c).balance;
        uint afterRecipientBalance = address(recipient).balance;

        bool directReverted;
        try c.withdrawReward{value: amount}(recipient) {
            directReverted = false;
        } catch {
            directReverted = true;
        }

        uint finalContractBalance = address(c).balance;

        require(
            reverted ||
            afterContractBalance + 100 == beforeContractBalance,
            "successful bonus must decrease contract balance by exactly 100 wei"
        );

        assert(
            directReverted ||
            address(recipient).balance < afterRecipientBalance ||
            finalContractBalance < afterContractBalance
        );
    }

    receive() external payable {}
}

